const { Given, When, Then } = require('@cucumber/cucumber');

// ---------------------------------------------------------------------------
// Given
// ---------------------------------------------------------------------------

Given('the app is loaded', function () {
  // Already loaded by Before hook in world.js; nothing to do.
});

Given('the todo list is empty', function () {
  // No pre-existing todos; state is already clean after loadApp().
});

Given('the user has added todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, bubbles: true }));
});

Given('the user has added completed todo {string}', function (title) {
  this['Given the user has added todo {string}'](title);
  const toggle = this.getTodoToggle(title);
  if (toggle && !toggle.checked) {
    toggle.click();
  }
});

// ---------------------------------------------------------------------------
// When
// ---------------------------------------------------------------------------

When('the user types {string} into the new-todo input and presses Enter', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('the user presses Enter without typing anything', function () {
  const input = this.document.querySelector('.new-todo');
  input.value = '';
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('the user toggles the checkbox for todo {string}', function (title) {
  const toggle = this.getTodoToggle(title);
  if (!toggle) throw new Error(`No toggle found for todo "${title}"`);
  toggle.click();
});

When('the user toggles the Mark all as complete checkbox', function () {
  const checkbox = this.document.querySelector('#toggle-all');
  checkbox.click();
});

When('the user double-clicks the label for todo {string}', function (title) {
  const label = this.getTodoLabel(title);
  if (!label) throw new Error(`No label found for todo "${title}"`);
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('the user types {string} into the edit input and presses Enter', function (title) {
  const edit = this.getEditingInput();
  if (!edit) throw new Error('No editing input found');
  edit.value = title;
  edit.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('the user types {string} into the edit input and blurs', function (title) {
  const edit = this.getEditingInput();
  if (!edit) throw new Error('No editing input found');
  edit.value = title;
  edit.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  edit.dispatchEvent(new this.window.Event('focusout', { bubbles: true }));
  edit.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('the user clears the edit input and presses Enter', function () {
  const edit = this.getEditingInput();
  if (!edit) throw new Error('No editing input found');
  edit.value = '';
  edit.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('the user types {string} into the edit input and presses Escape', function (title) {
  const edit = this.getEditingInput();
  if (!edit) throw new Error('No editing input found');
  edit.value = title;
  edit.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keypress', { key: 'Escape', keyCode: 27, bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keyup', { key: 'Escape', keyCode: 27, bubbles: true }));
});

When('the user clicks the destroy button for todo {string}', function (title) {
  const destroy = this.getTodoDestroy(title);
  if (!destroy) throw new Error(`No destroy button found for todo "${title}"`);
  destroy.click();
});

When('the user clicks the Clear completed button', function () {
  const btn = this.document.querySelector('.clear-completed');
  btn.click();
});

When('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

When('the app is reloaded', function () {
  const todos = this.loadTodosFromStorage();
  this.disposeApp();
  this.loadApp();
  this.restoreTodosToStorage(todos);
  this.disposeApp();
  this.loadApp();
});

// ---------------------------------------------------------------------------
// Then
// ---------------------------------------------------------------------------

Then('a todo {string} appears in the list', function (title) {
  const labels = Array.from(this.document.querySelectorAll('.todo-list .view label'));
  const found = labels.some(el => el.textContent === title);
  if (!found) throw new Error(`Expected todo "${title}" in list, not found. Labels: ${labels.map(l => l.textContent).join(', ')}`);
});

Then('the new-todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  if (input.value !== '') throw new Error(`Expected new-todo input empty, got "${input.value}"`);
});

Then('the item count shows {string}', function (text) {
  const strong = this.document.querySelector('.todo-count strong');
  const parent = this.document.querySelector('.todo-count');
  const actual = parent.textContent.trim();
  if (actual !== text) throw new Error(`Expected item count "${text}", got "${actual}"`);
});

Then('no todo is added to the list', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  if (items.length > 0) {
    throw new Error(`Expected empty list, found ${items.length} items`);
  }
});

Then('todo {string} is marked as completed', function (title) {
  const li = this.getTodoLi(title);
  if (!li) throw new Error(`No todo found for "${title}"`);
  if (!li.classList.contains('completed')) throw new Error(`Todo "${title}" is not marked completed`);
  const toggle = this.getTodoToggle(title);
  if (!toggle.checked) throw new Error(`Todo "${title}" checkbox is not checked`);
});

Then('todo {string} is not marked as completed', function (title) {
  const li = this.getTodoLi(title);
  if (!li) throw new Error(`No todo found for "${title}"`);
  if (li.classList.contains('completed')) throw new Error(`Todo "${title}" is still marked completed`);
  const toggle = this.getTodoToggle(title);
  if (toggle.checked) throw new Error(`Todo "${title}" checkbox is still checked`);
});

Then('all todos are marked as completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    if (!li.classList.contains('completed')) throw new Error(`Todo not completed: ${li.querySelector('label').textContent}`);
  }
});

Then('no todo is marked as completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    if (li.classList.contains('completed')) throw new Error(`Todo still completed: ${li.querySelector('label').textContent}`);
  }
});

Then('the Mark all as complete checkbox is not checked', function () {
  const checkbox = this.document.querySelector('#toggle-all');
  if (checkbox.checked) throw new Error('Mark all checkbox is checked but expected unchecked');
});

Then('the Mark all as complete checkbox is checked', function () {
  const checkbox = this.document.querySelector('#toggle-all');
  if (!checkbox.checked) throw new Error('Mark all checkbox is unchecked but expected checked');
});

Then('todo {string} is in editing mode', function (title) {
  const li = this.getTodoLi(title);
  if (!li) throw new Error(`No todo found for "${title}"`);
  if (!li.classList.contains('editing')) throw new Error(`Todo "${title}" is not in editing mode`);
  const edit = li.querySelector('.edit');
  if (this.document.activeElement !== edit && !edit.matches(':focus')) {
    throw new Error(`Edit input for "${title}" is not focused`);
  }
});

Then('todo {string} is not in editing mode', function (title) {
  const li = this.getTodoLi(title);
  if (!li) throw new Error(`No todo found for "${title}"`);
  if (li.classList.contains('editing')) throw new Error(`Todo "${title}" is still in editing mode`);
});

Then('no todo {string} exists', function (title) {
  const labels = Array.from(this.document.querySelectorAll('.todo-list .view label'));
  const found = labels.some(el => el.textContent === title);
  if (found) throw new Error(`Todo "${title}" should not exist but was found`);
});

Then('the todo list is empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  if (items.length > 0) {
    throw new Error(`Expected empty list, found ${items.length} items`);
  }
});

Then('the Clear completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  const style = this.window.getComputedStyle(btn);
  if (style.display !== 'none' && btn.offsetParent !== null) {
    throw new Error('Clear completed button is visible but expected hidden');
  }
});

Then('no todo {string} appears in the list', function (title) {
  const labels = Array.from(this.document.querySelectorAll('.todo-list .view label'));
  const found = labels.some(el => el.textContent === title);
  if (found) throw new Error(`Todo "${title}" should not appear in list but was found`);
});

Then('the {string} filter link is selected', function (filterName) {
  const links = this.document.querySelectorAll('.filters a');
  const link = Array.from(links).find(a => a.textContent === filterName);
  if (!link) throw new Error(`Filter link "${filterName}" not found`);
  if (!link.classList.contains('selected')) throw new Error(`Filter link "${filterName}" is not selected`);
});

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  const style = this.window.getComputedStyle(main);
  if (style.display !== 'none' && main.offsetParent !== null) {
    throw new Error('Main section is visible but expected hidden');
  }
});

Then('the footer is hidden', function () {
  const footer = this.document.querySelector('.footer');
  const style = this.window.getComputedStyle(footer);
  if (style.display !== 'none' && footer.offsetParent !== null) {
    throw new Error('Footer is visible but expected hidden');
  }
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  const style = this.window.getComputedStyle(main);
  if (style.display === 'none') {
    throw new Error('Main section is hidden but expected visible');
  }
});

Then('the footer is visible', function () {
  const footer = this.document.querySelector('.footer');
  const style = this.window.getComputedStyle(footer);
  if (style.display === 'none') {
    throw new Error('Footer is hidden but expected visible');
  }
});

